import{_ as i,o as s,c as l,a0 as e}from"./chunks/framework.jwovEGr5.js";const u=JSON.parse('{"title":"ai生活化类比","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"概念学习/ai相关/ai生活化类比.md","filePath":"概念学习/ai相关/ai生活化类比.md"}'),p={name:"概念学习/ai相关/ai生活化类比.md"};function t(n,a,o,h,r,d){return s(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="ai生活化类比" tabindex="-1">ai生活化类比 <a class="header-anchor" href="#ai生活化类比" aria-label="Permalink to &quot;ai生活化类比&quot;">​</a></h1><p>内容仅供学习参考</p><h2 id="一个ai输出细节" tabindex="-1">一个ai输出细节 <a class="header-anchor" href="#一个ai输出细节" aria-label="Permalink to &quot;一个ai输出细节&quot;">​</a></h2><p>平常在使用ai的过程中，我们会经常询问ai某个概念的含义，以及它与其它概念之间的区别或是联系</p><p>此时我们可能发现，ai不仅会用术语向我们解释，还会使用一个小妙招：生活化类比</p><p>类比可以化繁为简，其作用十分强大，几乎可以瞬间让我们理解本身复杂的关系</p><p>仔细观察ai给出的类比，我很惊奇于ai能够找到如此普遍而准确的例子，这不禁让我思考ai是如何做到的。于是稍稍研究了一下，整理成以下的笔记</p><h2 id="底层实现逻辑" tabindex="-1">底层实现逻辑 <a class="header-anchor" href="#底层实现逻辑" aria-label="Permalink to &quot;底层实现逻辑&quot;">​</a></h2><p>这种生活化类比的输出实现是多模块协同结果，全程基于大模型预训练+推理时Prompt约束+语义匹配检索</p><p>需要解决的问题可以大致分成两部分：</p><ol><li>如何生成类比</li><li>怎么从海量的场景当中选出我们需要的贴切、易懂的例子</li></ol><h3 id="如何生成类比" tabindex="-1">如何生成类比 <a class="header-anchor" href="#如何生成类比" aria-label="Permalink to &quot;如何生成类比&quot;">​</a></h3><br><h5 id="预训练阶段" tabindex="-1">预训练阶段 <a class="header-anchor" href="#预训练阶段" aria-label="Permalink to &quot;预训练阶段&quot;">​</a></h5><p>总目标是建立<code>概念-生活案例</code>语义关联</p><p>训练数据包含三类核心文本，提前在模型参数里埋下映射关系</p><p><strong>科普、编程、技术教程类文本</strong></p><p>网上大量教程都会用类比讲解技术，模型在预训练时学习：抽象专业术语与通俗生活化事物的对应逻辑、比喻结构</p><p><strong>日常问答、教辅、通俗科普内容</strong></p><p>中小学教辅、知乎/小红书通俗讲解、行业大白话科普，统一教会模型一套固定类比范式</p><p><strong>对话对齐数据（<a href="#sft">SFT</a>微调）</strong></p><p>人工标注大量需求：<code>用户问专业名词，输出先定义+生活化类比辅助理解</code>，强制模型养成“解释概念优先搭配通俗类比”的输出习惯，也就是我们观察到的固定行为。</p><h3 id="如何检索类比" tabindex="-1">如何检索类比 <a class="header-anchor" href="#如何检索类比" aria-label="Permalink to &quot;如何检索类比&quot;">​</a></h3><br><h5 id="推理时的执行流程" tabindex="-1">推理时的执行流程 <a class="header-anchor" href="#推理时的执行流程" aria-label="Permalink to &quot;推理时的执行流程&quot;">​</a></h5><ol><li><p>语义拆解，识别输入的核心概念，提取它的关键属性</p></li><li><p>检索候选类比库（隐式语义匹配）</p></li></ol><p>在模型内部知识空间，匹配具备相同核心特征的现实事物，生成一批候选情景</p><ol start="3"><li><p>多维度打分筛选，淘汰不合适案例。使用一套隐性打分规则，自动过滤违和场景，只保留最优1~2个生活化类比</p></li><li><p>结构化组织输出，先下定义，再把概念每个特征和类比事物一一对应解释，最后补充边界（类比只是近似，存在区别，避免误解）</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>多维匹配打分机制，模型自动计算匹配度，取最高分场景</p><p>包含核心功能匹配、生活化程度（大众场景）、复杂度匹配（防止化繁为繁）、区分边界校验（防止误导）。同时，采用负样本约束、上下文连贯性约束、安全与歧义过滤</p></div><h2 id="疑问" tabindex="-1">疑问 <a class="header-anchor" href="#疑问" aria-label="Permalink to &quot;疑问&quot;">​</a></h2><h3 id="怎么获得、整理训练数据" tabindex="-1">怎么获得、整理训练数据 <a class="header-anchor" href="#怎么获得、整理训练数据" aria-label="Permalink to &quot;怎么获得、整理训练数据&quot;">​</a></h3><br><h5 id="渠道" tabindex="-1">渠道 <a class="header-anchor" href="#渠道" aria-label="Permalink to &quot;渠道&quot;">​</a></h5><p>公开合规全网爬虫语料、正版书籍 &amp; 教材语料、高质量中文开源教育数据集（如FineWeb-Edu等）</p><h5 id="整理清洗" tabindex="-1">整理清洗 <a class="header-anchor" href="#整理清洗" aria-label="Permalink to &quot;整理清洗&quot;">​</a></h5><p>大致包含下面的内容：</p><p>正文提取、编码归一化、繁简统一、双层去重（精确哈希/MinHash模糊去重）</p><p>语种过滤、脏文本过滤（短句、乱码、病句）、模型质量打分过滤（用小模型给文本通顺度、逻辑合理性打分）</p><p>敏感内容/隐私脱敏、按领域分层（科普类比单独做一个数据桶，提升权重）</p><h3 id="预训练阶段的语义关联怎么建立" tabindex="-1">预训练阶段的语义关联怎么建立 <a class="header-anchor" href="#预训练阶段的语义关联怎么建立" aria-label="Permalink to &quot;预训练阶段的语义关联怎么建立&quot;">​</a></h3><p>预训练没有手动建对照表、没有专门给类比打标签，完全依靠Transformer自注意力机制+连续文本的上下文共现学习，把<code>专业术语、类比关键词、日常事物</code>三者的向量嵌入拉近，形成隐性语义关联。</p><p>后续微调只是强化使用习惯，底层的类比映射关系全部是预训练从文本文字里自动学出来的。</p><h5 id="词向量-embedding-是关联的载体" tabindex="-1">词向量（Embedding）是关联的载体 <a class="header-anchor" href="#词向量-embedding-是关联的载体" aria-label="Permalink to &quot;词向量（Embedding）是关联的载体&quot;">​</a></h5><ol><li>所有文字（词语、成语、短句）都会被编码器压缩为一组高维数字向量</li><li>语义越相近、经常一起出现的词，向量在空间上距离越近</li><li>模型所有联想、类比、推理，本质都是向量距离计算</li></ol><h5 id="建立关联三种核心模式" tabindex="-1">建立关联三种核心模式 <a class="header-anchor" href="#建立关联三种核心模式" aria-label="Permalink to &quot;建立关联三种核心模式&quot;">​</a></h5><p><strong>上下文共现学习</strong></p><p>文本范式</p><p><code>专业名词</code>，可以理解成<code>生活化事物</code>，它的<code>A</code>作用就像事物的<code>A</code>功能，<code>B</code>特性对应事物<code>B</code>特性</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例文本：</span></span>
<span class="line"><span>内存就像桌面，硬盘是柜子，正在运行的程序放在桌面方便快速取用。</span></span></code></pre></div><p>模型在做自监督预训练任务（<a href="#mlm掩码预测">MLM掩码预测</a>/下一句预测）时：</p><ol><li>随机盖住其中一个词，用前后文预测被盖住的词</li><li>长期大量看见<code>内存</code>后面紧跟<code>就像桌面</code>，模型会强制把两个词的语义绑定</li><li>同时绑定功能描述：<code>快速取用</code>同时关联内存、桌面两个主体</li></ol><p>长期海量文本投喂后形成三层关联</p><ol><li>名词-类比实物（内存-桌面）</li><li>名词特征-实物特征（高速读写-随手拿东西）</li><li>适用场景联动（程序加载-物品摆上桌面）</li></ol><p>只要触发任意一个关键词，注意力权重就会流向整套类比词组</p><p><strong>长文本逻辑链路绑定</strong></p><p>单纯词语共现只会做简单同义词联想，想要结构对齐类比（A整体结构≈B整体结构），依靠长段落文本学习。</p><p>以<code>服务器=饭店</code>长科普文举例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>前端是饭店前厅，负责展示页面、接待客人</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后端服务是后厨，接收前厅的点餐指令、加工业务逻辑</span></span>
<span class="line"><span></span></span>
<span class="line"><span>端口就是饭店的门，不同门店用不同门口接单。</span></span></code></pre></div><p>Transformer的多头自注意力可以捕捉远距离依赖</p><p>即使<code>前端</code>和<code>前厅</code>相隔十几个字，模型依然会计算二者的注意力权重，构建结构化整体映射，而不只是单个词语绑定。</p><p>好处：类比是整套逻辑对应，不会出现局部逻辑错乱的强行类比。</p><p><strong>同义转述文本压缩关联（多场景合并统一类比）</strong></p><p>互联网里同一个知识点会有几十上百篇科普文章，用不同话术做同一个类比：</p><ul><li>文章 1：内存如同书桌</li><li>文章 2：内存好比操作台</li><li>文章 3：内存就是桌面工作台</li></ul><p>预训练模糊去重不会删掉全部转述，保留合理变体。</p><p>模型学习到：书桌、操作台、桌面是等价类比物，全部和<code>内存</code>向量靠近，丰富类比素材库，回答不会只有单一例子。</p><h5 id="分工" tabindex="-1">分工 <a class="header-anchor" href="#分工" aria-label="Permalink to &quot;分工&quot;">​</a></h5><p>预训练：搭建全部（概念-生活事物）语义关联思维导图</p><p><a href="#sft">SFT</a>指令微调：行为约束</p><p><a href="#rlhf">RLHF</a>强化学习：择优</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>可以简单类比为：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>预训练=看书掌握全部知识</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SFT=一套标准答题模板+标准答案刷题，固定答题思路和格式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RLHF=批改卷子，优化答题优劣</span></span></code></pre></div><h3 id="推理时的关键属性怎么提取" tabindex="-1">推理时的关键属性怎么提取 <a class="header-anchor" href="#推理时的关键属性怎么提取" aria-label="Permalink to &quot;推理时的关键属性怎么提取&quot;">​</a></h3><p>整体分为两步</p><ol><li>输入编码阶段：特征解构</li><li>注意力检索阶段：用属性匹配预训练建好的类比语义库</li></ol><blockquote><p>模型没有显式“if判断提取属性”的代码逻辑，全部依托Token嵌入+多头自注意力+上下文特征聚焦完成属性抽取，分为原生模型自主提取、Prompt引导提取两种模式。</p></blockquote><h5 id="token化-向量嵌入-基础特征落地" tabindex="-1">Token化+向量嵌入，基础特征落地 <a class="header-anchor" href="#token化-向量嵌入-基础特征落地" aria-label="Permalink to &quot;Token化+向量嵌入，基础特征落地&quot;">​</a></h5><p>用户输入文本会被分词器切分为最小Token，每个Token映射为高维Embedding向量。</p><p>向量天然携带基础语义属性：</p><ul><li>名词向量：承载角色、主体、功能属性</li><li>动词向量：承载动作、行为属性</li><li>形容词/状态词：承载状态、约束属性</li><li>连词（因为、导致）：承载因果属性</li></ul><p>需要提取的关键属性</p><ol><li>主体角色属性</li><li>核心动作属性</li><li>核心约束/状态属性</li><li>因果逻辑属性</li><li>核心功能属性</li></ol><h5 id="多头自注意力-聚焦关键属性-核心步骤" tabindex="-1">多头自注意力，聚焦关键属性（核心步骤） <a class="header-anchor" href="#多头自注意力-聚焦关键属性-核心步骤" aria-label="Permalink to &quot;多头自注意力，聚焦关键属性（核心步骤）&quot;">​</a></h5><p>Transformer多头注意力（Multi-Head Attention）分工提取不同维度属性，每个头专攻一类特征：</p><ul><li>头1：主体抽取头：聚焦句子里的核心名词，过滤修饰性形容词、冗余定语，锁定核心主体</li><li>头2：动作行为抽取头：重点捕捉谓语动词、动宾结构，提取全部交互动作</li><li>头3：状态 &amp; 条件头：识别限定词，判断运行状态（正常/异常、启用/停用）</li><li>头4：因果逻辑头：捕捉上下文因果关系、条件关系</li><li>头5：整体结构头：串联前面4个头的特征，形成完整结构化属性集合。</li></ul><blockquote><p>核心逻辑：注意力权重高，说明这个Token是关键属性，权重极低的修饰词直接被忽略。</p></blockquote><h5 id="属性结构化隐性编码" tabindex="-1">属性结构化隐性编码 <a class="header-anchor" href="#属性结构化隐性编码" aria-label="Permalink to &quot;属性结构化隐性编码&quot;">​</a></h5><p>多头注意力输出拼接后，模型内部形成一个隐性特征向量簇，等价于结构化字典</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;主体&quot;: &quot;本地后端服务&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;对向主体&quot;: &quot;浏览器客户端&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;核心动作&quot;: &quot;拒绝接入&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;运行状态&quot;: &quot;服务关闭、未运行&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;因果&quot;: &quot;服务未启动 → 拒绝连接&quot;,</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;核心矛盾&quot;: &quot;服务端点未就绪，无法响应外部请求&quot;</span></span></code></pre></div><p>模型不会输出这个字典，但后续所有类比、推理、生成全部基于这个特征集合</p><h5 id="基于属性向量召回类比素材" tabindex="-1">基于属性向量召回类比素材 <a class="header-anchor" href="#基于属性向量召回类比素材" aria-label="Permalink to &quot;基于属性向量召回类比素材&quot;">​</a></h5><p>拿着上面整套属性向量，在预训练的语义向量空间做<a href="#相似度检测">相似度检索</a></p><p>寻找同时匹配的生活实体,得到匹配结果</p><p>随后基于属性一一对应生成类比</p><h3 id="怎么获得现实事物的核心特征" tabindex="-1">怎么获得现实事物的核心特征 <a class="header-anchor" href="#怎么获得现实事物的核心特征" aria-label="Permalink to &quot;怎么获得现实事物的核心特征&quot;">​</a></h3><p>整体分为人工结构化拆解、规则自动化抽取、模型特征提取、知识库结构化沉淀4套方案，从手工落地到工业自动化全覆盖，最终产出事物特征字典，用来和技术概念特征做向量匹配、类比对齐。</p><p>核心原则：只保留功能、角色、行为、因果、约束，舍弃外形、材质等表层属性，才能实现精准的生活化类比匹配。</p><h3 id="如何处理不同场景的多义" tabindex="-1">如何处理不同场景的多义 <a class="header-anchor" href="#如何处理不同场景的多义" aria-label="Permalink to &quot;如何处理不同场景的多义&quot;">​</a></h3><p>同一个现实事物/技术名词具备多组完全独立的核心特征集合，直接整体向量化会造成向量混淆、类比错配。</p><h5 id="多义实体拆分-底层方案" tabindex="-1">多义实体拆分（底层方案） <a class="header-anchor" href="#多义实体拆分-底层方案" aria-label="Permalink to &quot;多义实体拆分（底层方案）&quot;">​</a></h5><ol><li>人工拆分（高精度种子库）：对高频类比常用事物手动拆分词义，各自做结构化特征，分开入库。</li></ol><p>词义分别拼接文本、分别生成向量、单独存入向量库，打上场景标签</p><p>示例：房门（多义拆分）</p><p>词义A：通行开关</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;通道开关&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;开合控制通行&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;开/闭&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;同一时间单向开合&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;effect&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;关门阻断通行&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>词义B：专属出入口（端口类比）</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;独立出入口&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;专属通道接入&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;占用/空闲&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;一个房门只能一户使用&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;effect&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;房门被占用则无法使用该通道接入&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="2"><li>自动化多词义拆分（批量处理）</li><li>存储改造：向量库带上场景标签</li></ol><h5 id="上下文消歧" tabindex="-1">上下文消歧 <a class="header-anchor" href="#上下文消歧" aria-label="Permalink to &quot;上下文消歧&quot;">​</a></h5><ol><li>基于查询特征直接限定业务域</li><li>上下文窗口消歧</li><li>关键词域分类器</li></ol><h5 id="向量层优化-解决多义向量坍缩问题" tabindex="-1">向量层优化：解决多义向量坍缩问题 <a class="header-anchor" href="#向量层优化-解决多义向量坍缩问题" aria-label="Permalink to &quot;向量层优化：解决多义向量坍缩问题&quot;">​</a></h5><ol><li>禁止实体整体Embedding，使用结构化特征文本Embedding</li></ol><p>错误做法：直接对词语编码，融合全部含义，向量混沌。</p><p>正确做法：使用拆分后的功能特征描述文本做向量。</p><p>两段文本语义完全不同，向量自然远离，不会互相干扰。</p><ol start="2"><li>特征维度加权，压制无关语义分量</li></ol><p>针对查询场景做特征权重缩放：</p><ul><li>资源独占场景：拉高【约束】权重</li><li>开关通断场景：拉高【状态 + 动作】权重</li></ul><p>向量计算时加权融合特征，强化目标语义，弱化次要语义。</p><ol start="3"><li>向量聚类清洗</li></ol><p>入库后做聚类：同一个原始事物的多条语义向量会被分到不同聚类簇，校验聚类结果，若出现多词义向量扎堆，说明特征拆分不足，重新拆分。</p><h2 id="概念解释" tabindex="-1">概念解释 <a class="header-anchor" href="#概念解释" aria-label="Permalink to &quot;概念解释&quot;">​</a></h2><h3 id="sft" tabindex="-1">SFT <a class="header-anchor" href="#sft" aria-label="Permalink to &quot;SFT&quot;">​</a></h3><p>Supervised Fine-Tuning，有监督微调</p><p>是大模型基座训练完成之后，最核心的一轮定向训练手段，也是让模型 固定输出格式、说话风格的核心手段。</p><p>其具有样本格式（单条训练数据）</p><p>批量几千到几万条这种问答对，就是SFT训练集</p><h5 id="核心原理" tabindex="-1">核心原理 <a class="header-anchor" href="#核心原理" aria-label="Permalink to &quot;核心原理&quot;">​</a></h5><ol><li>冻结大部分基座参数（LoRA 微调只训少量参数，成本更低）</li><li>输入格式固定对话格式</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;System&gt;人设指令</span></span>
<span class="line"><span>&lt;User&gt;用户问题</span></span>
<span class="line"><span>&lt;Assistant&gt;标准标准答案</span></span></code></pre></div><p>训练形式包含全量微调、LoRA微调两种主流方式</p><ol start="3"><li>训练目标：让模型在看到System+User输入时，最大概率复刻给出标注好的标准回答</li></ol><blockquote><p>不是学习新知识，是对齐行为、对齐格式、对齐话术逻辑。</p></blockquote><h5 id="sft如何强化关键属性精准提取" tabindex="-1">SFT如何强化关键属性精准提取 <a class="header-anchor" href="#sft如何强化关键属性精准提取" aria-label="Permalink to &quot;SFT如何强化关键属性精准提取&quot;">​</a></h5><p>基座模型偶尔会抓错次要特征，SFT通过标注数据强制模型聚焦核心属性，减少特征跑偏</p><ol><li>训练样本强制对齐<code>属性拆解-类比</code>链路</li></ol><p>标注样本结构固定：</p><p>用户提问 → 内部拆解核心属性 → 基于属性做类比解释</p><p>模型学习到：想要输出正确类比，第一步必须提取核心特征，不能抓住细枝末节做比喻。</p><ol start="2"><li>System Prompt固定提取逻辑</li></ol><p>比如固定人设：</p><p>讲解前先提炼事物：角色、动作、运行状态、因果，再用生活物品一一对应特征做类比。</p><p>在推理时直接引导注意力头优先拆解四大核心属性，杜绝无效特征。</p><h3 id="mlm掩码预测" tabindex="-1">MLM掩码预测 <a class="header-anchor" href="#mlm掩码预测" aria-label="Permalink to &quot;MLM掩码预测&quot;">​</a></h3><p>Masked Language Model，掩码语言模型。</p><p>是BERT类编码器模型核心预训练任务，也是早期中文基座模型构建词语语义、上下文关联、一词多义理解的核心任务。</p><p>GPT用的是自回归下一句预测（CLM），BERT用MLM双向上下文学习。</p><h5 id="简单步骤" tabindex="-1">简单步骤 <a class="header-anchor" href="#简单步骤" aria-label="Permalink to &quot;简单步骤&quot;">​</a></h5><p>随机盖住句子里的词，让模型猜被盖住的词</p><p>拿一段完整自然文本</p><p>例如</p><p>··· 内存就像桌面，用来临时存放正在使用的程序 ···</p><p>随机挑选句子中15%的Token做掩码遮挡</p><ul><li>80% 直接替换为特殊掩码符号[MASK]</li><li>10% 随机替换成一个无关错词（增加鲁棒性）</li><li>10% 保持原词不变</li></ul><p>例如（遮挡后）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内存就像[MASK]，用来临时存放正在使用的程序</span></span></code></pre></div><p>把处理后的句子送入模型，训练目标：根据左右全部上下文，精准还原出被遮住的词是<code>桌面</code>。</p><h3 id="rlhf" tabindex="-1">RLHF <a class="header-anchor" href="#rlhf" aria-label="Permalink to &quot;RLHF&quot;">​</a></h3><p>Reinforcement Learning from Human Feedback，基于人类反馈的强化学习</p><p>是大模型三阶段训练的最后一步</p><h5 id="核心步骤" tabindex="-1">核心步骤 <a class="header-anchor" href="#核心步骤" aria-label="Permalink to &quot;核心步骤&quot;">​</a></h5><ol><li>SFT模型预热（前置条件）</li></ol><p>必须先完成SFT微调模型，作为强化学习的初始底座，不能直接用原生预训练模型做RLHF</p><ol start="2"><li>训练奖励模型RM（Reward Model）</li></ol><p>人工标注员对多条回答从优到劣排序打分，用打分数据训练一个独立的奖励模型</p><p>核心作用：让机器学会自动判断</p><ol start="3"><li>PPO强化学习微调主模型</li></ol><blockquote><p>人工标注成本极高，大厂后期会用成熟大模型替代人工打分（RLAIF），用高质量模型充当打分员训练奖励模型，大幅降低人工成本</p></blockquote><h5 id="实施落地" tabindex="-1">实施落地 <a class="header-anchor" href="#实施落地" aria-label="Permalink to &quot;实施落地&quot;">​</a></h5><p>RLHF无法新增底层知识：RLHF无法合理比喻预训练没学到的事物特征、类比关系</p><p>RLHF是上层偏好优化，不能替代预训练+SFT</p><p>个人小模型定制：一般做到SFT-LoRA就足够，RLHF算力、数据成本极高，仅大厂主模型会完整部署PPO强化学习</p><h3 id="相似度检测" tabindex="-1">相似度检测 <a class="header-anchor" href="#相似度检测" aria-label="Permalink to &quot;相似度检测&quot;">​</a></h3><p>文本/词语经过Embedding编码后，变成N维浮点向量，形如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vec = [0.12, 0.45, -0.22, 0.78, ...]</span></span></code></pre></div><p>核心公理：语义越相近的文本，向量在高维空间几何距离越近；语义差距越大，距离越远。</p><p>相似度计算本质就是：用几何公式计算两个向量的远近。</p><p><strong>常用三种算法：</strong></p><p>余弦相似度（主流首选）、欧氏距离、曼哈顿距离。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>大模型检索、类比素材召回、文本去重、特征匹配全部用余弦相似度。</p><p>工业场景必须用ANN向量索引，提高速度</p><p>文本去重：余弦相似度≥0.85判定为近似重复文本</p><p>精准素材召回：阈值≥0.8强匹配</p><p>宽泛素材召回：阈值0.6~0.8拓展类比案例</p></div>`,179)])])}const k=i(p,[["render",t]]);export{u as __pageData,k as default};
